import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.Arrays;
import java.util.HashSet;

import org.eclipse.rdf4j.model.Literal;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.model.util.LiteralUtilException;
import org.eclipse.rdf4j.model.vocabulary.RDF;
import org.eclipse.rdf4j.model.vocabulary.XSD;
import org.eclipse.rdf4j.rio.ParserConfig;
import org.eclipse.rdf4j.rio.RDFParseException;
import org.eclipse.rdf4j.rio.helpers.BasicParserSettings;
import org.eclipse.rdf4j.rio.helpers.ParseErrorCollector;
import org.eclipse.rdf4j.rio.helpers.RDFParserHelper;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

class BCP47LanguageHandlerTest {

	private static final String LABEL = "test-a";
	private static final ValueFactory VALUE_FACTORY = SimpleValueFactory.getInstance();
	private final BCP47LanguageHandler handler = new BCP47LanguageHandler();

	private ParserConfig parserConfig;
	private ParseErrorCollector errorListener;

	@BeforeEach
	void setUp() {
		parserConfig = new ParserConfig();
		parserConfig.set(BasicParserSettings.LANGUAGE_HANDLERS, Arrays.asList(handler));
		parserConfig.setNonFatalErrors(new HashSet<>());
		errorListener = new ParseErrorCollector();
	}

	@Test
	void emptyTagIsNotRecognizedAsBcp47() {
		assertFalse(handler.isRecognizedLanguage(""));
	}

	@Test
	void normalizingEmptyTagUsesLiteralUtilException() {
		assertThrows(LiteralUtilException.class, () -> handler.normalizeLanguage(LABEL, "", VALUE_FACTORY));
	}

	@Test
	void emptyLanguageIsRecoveredWhenDatatypeVerificationIsLenient() {
		parserConfig.set(BasicParserSettings.VERIFY_DATATYPE_VALUES, false);
		parserConfig.set(BasicParserSettings.NORMALIZE_LANGUAGE_TAGS, true);

		Literal literal = RDFParserHelper.createLiteral(LABEL, "", null, parserConfig, errorListener, VALUE_FACTORY);

		assertEquals(LABEL, literal.getLabel());
		assertFalse(literal.getLanguage().isPresent());
		assertEquals(XSD.STRING, literal.getDatatype());
		assertTrue(errorListener.getErrors().isEmpty());
	}

	@Test
	void emptyLanguageDoesNotLeakModelExceptionWhenDatatypeVerificationIsStrict() {
		parserConfig.set(BasicParserSettings.VERIFY_DATATYPE_VALUES, true);
		parserConfig.set(BasicParserSettings.NORMALIZE_LANGUAGE_TAGS, true);

		assertThrows(RDFParseException.class,
				() -> RDFParserHelper.createLiteral(LABEL, "", null, parserConfig, errorListener, VALUE_FACTORY));
		assertEquals(1, errorListener.getFatalErrors().size());
	}

	@Test
	void emptyLanguageUsesUnknownLanguageSetting() {
		parserConfig.set(BasicParserSettings.FAIL_ON_UNKNOWN_LANGUAGES, true);

		assertThrows(RDFParseException.class,
				() -> RDFParserHelper.createLiteral(LABEL, "", null, parserConfig, errorListener, VALUE_FACTORY));
		assertEquals(1, errorListener.getErrors().size());
		assertTrue(errorListener.getFatalErrors().isEmpty());
	}

	@Test
	void nonFatalUnknownEmptyLanguageCanBeRecovered() {
		parserConfig.set(BasicParserSettings.VERIFY_DATATYPE_VALUES, false);
		parserConfig.set(BasicParserSettings.NORMALIZE_LANGUAGE_TAGS, true);
		parserConfig.set(BasicParserSettings.FAIL_ON_UNKNOWN_LANGUAGES, true);
		parserConfig.addNonFatalError(BasicParserSettings.FAIL_ON_UNKNOWN_LANGUAGES);

		Literal literal = RDFParserHelper.createLiteral(LABEL, "", null, parserConfig, errorListener, VALUE_FACTORY);

		assertEquals(XSD.STRING, literal.getDatatype());
		assertEquals(1, errorListener.getErrors().size());
	}

	@Test
	void emptyLanguageWithLangStringDatatypesFollowsDatatypeVerificationSetting() {
		parserConfig.set(BasicParserSettings.VERIFY_DATATYPE_VALUES, false);
		parserConfig.set(BasicParserSettings.NORMALIZE_LANGUAGE_TAGS, true);

		for (var datatype : Arrays.asList(RDF.LANGSTRING, RDF.DIRLANGSTRING)) {
			Literal literal = RDFParserHelper.createLiteral(LABEL, "", datatype, parserConfig, errorListener,
					VALUE_FACTORY);
			assertFalse(literal.getLanguage().isPresent());
			assertEquals(XSD.STRING, literal.getDatatype());
		}
	}

	@Test
	void emptyLanguageWithLangStringDatatypesFailsWhenStrict() {
		parserConfig.set(BasicParserSettings.VERIFY_DATATYPE_VALUES, true);
		parserConfig.set(BasicParserSettings.NORMALIZE_LANGUAGE_TAGS, true);

		for (var datatype : Arrays.asList(RDF.LANGSTRING, RDF.DIRLANGSTRING)) {
			assertThrows(RDFParseException.class,
					() -> RDFParserHelper.createLiteral(LABEL, "", datatype, parserConfig, errorListener,
							VALUE_FACTORY));
		}
		assertEquals(2, errorListener.getFatalErrors().size());
	}

	@Test
	void emptyLanguageFromDirectionSuffixIsRecoveredWhenLenient() {
		parserConfig.set(BasicParserSettings.VERIFY_DATATYPE_VALUES, false);
		parserConfig.set(BasicParserSettings.NORMALIZE_LANGUAGE_TAGS, true);

		for (String languageAndDirection : Arrays.asList("--ltr", "--rtl")) {
			Literal literal = RDFParserHelper.createLiteral(LABEL, languageAndDirection, null, parserConfig,
					errorListener, VALUE_FACTORY);
			assertFalse(literal.getLanguage().isPresent());
			assertEquals(XSD.STRING, literal.getDatatype());
		}
	}

	@Test
	void emptyLanguageFromDirectionSuffixDoesNotLeakModelExceptionWhenStrict() {
		parserConfig.set(BasicParserSettings.VERIFY_DATATYPE_VALUES, true);
		parserConfig.set(BasicParserSettings.NORMALIZE_LANGUAGE_TAGS, true);

		for (String languageAndDirection : Arrays.asList("--ltr", "--rtl")) {
			assertThrows(RDFParseException.class,
					() -> RDFParserHelper.createLiteral(LABEL, languageAndDirection, null, parserConfig, errorListener,
							VALUE_FACTORY));
		}
		assertEquals(2, errorListener.getFatalErrors().size());
	}

	@Test
	void emptyLanguageWithExplicitDatatypeRemainsTyped() {
		Literal literal = RDFParserHelper.createLiteral(LABEL, "", XSD.STRING, parserConfig, errorListener,
				VALUE_FACTORY);

		assertFalse(literal.getLanguage().isPresent());
		assertEquals(XSD.STRING, literal.getDatatype());
	}

	@Test
	void emptyLanguageIsRecoveredWhenNormalizationIsDisabled() {
		parserConfig.set(BasicParserSettings.NORMALIZE_LANGUAGE_TAGS, false);
		parserConfig.set(BasicParserSettings.VERIFY_DATATYPE_VALUES, false);

		Literal literal = RDFParserHelper.createLiteral(LABEL, "", null, parserConfig, errorListener, VALUE_FACTORY);

		assertFalse(literal.getLanguage().isPresent());
		assertEquals(XSD.STRING, literal.getDatatype());
	}

	@Test
	void validPlainTypedLanguageAndDirectionalLiteralsRemainSupported() {
		parserConfig.set(BasicParserSettings.VERIFY_DATATYPE_VALUES, false);
		parserConfig.set(BasicParserSettings.NORMALIZE_LANGUAGE_TAGS, true);

		Literal plain = RDFParserHelper.createLiteral(LABEL, null, null, parserConfig, errorListener, VALUE_FACTORY);
		Literal typed = RDFParserHelper.createLiteral(LABEL, null, XSD.STRING, parserConfig, errorListener,
				VALUE_FACTORY);
		Literal language = RDFParserHelper.createLiteral(LABEL, "EN-us", null, parserConfig, errorListener,
				VALUE_FACTORY);
		Literal ltr = RDFParserHelper.createLiteral(LABEL, "EN-us--ltr", null, parserConfig, errorListener,
				VALUE_FACTORY);
		Literal rtl = RDFParserHelper.createLiteral(LABEL, "ar--rtl", null, parserConfig, errorListener,
				VALUE_FACTORY);

		assertEquals(XSD.STRING, plain.getDatatype());
		assertEquals(XSD.STRING, typed.getDatatype());
		assertEquals("en-US", language.getLanguage().orElse(null));
		assertEquals(RDF.LANGSTRING, language.getDatatype());
		assertEquals("en-US", ltr.getLanguage().orElse(null));
		assertEquals(Literal.BaseDirection.LTR, ltr.getBaseDirection());
		assertEquals(RDF.DIRLANGSTRING, ltr.getDatatype());
		assertEquals("ar", rtl.getLanguage().orElse(null));
		assertEquals(Literal.BaseDirection.RTL, rtl.getBaseDirection());
		assertEquals(RDF.DIRLANGSTRING, rtl.getDatatype());

		parserConfig.set(BasicParserSettings.NORMALIZE_LANGUAGE_TAGS, false);
		Literal unnormalized = RDFParserHelper.createLiteral(LABEL, "EN-us", null, parserConfig, errorListener,
				VALUE_FACTORY);
		assertEquals("EN-us", unnormalized.getLanguage().orElse(null));
	}
}
